class User {
    int id;
    String name;
    String email;

    User() {
        // No-argument constructor
    }

    User(int id) {
        this.id = id;
    }

    User(int id, String name) {
        this.id = id;
        this.name = name;
    }

    User(int id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    void register() {
        System.out.println(name + " is registered");
    }

    void login() {
        System.out.println(name + " has logged in");
    }
}

public class UserApplication {
    public static void main(String[] args) {
        User user1 = new User();
        User user2 = new User(10);
        User user3 = new User(20, "Asha");
        User user4 = new User(30, "Raghu", "raghu@example.com");

        System.out.println(user1.id + " " + user1.name + " " + user1.email);
        System.out.println(user2.id + " " + user2.name + " " + user2.email);
        System.out.println(user3.id + " " + user3.name + " " + user3.email);
        System.out.println(user4.id + " " + user4.name + " " + user4.email);

        user4.register();
        user4.login();
    }
}

class User {
    int id;
    String name;

    User(int id, String name) {
        id = id;
